using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class C02Restore {public static object Run(){if(Application.isPlaying)throw new Exception("Edit mode required");var s=SceneManager.GetActiveScene();if(!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 required");var repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var output=repo+"/Docs/검수/2026-11-08_C02_Security/";var backup=JObject.Parse(File.ReadAllText(output+"backup.json"));string copy=Path.Combine((string)backup["backup"],"editing_after_play.unity");if(!EditorSceneManager.SaveScene(s,copy,true))throw new Exception("Post-play backup failed");bool dirty=s.isDirty;if(dirty&&!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var result=new{scene=s.path,postPlayBackup=copy,preservedEditChanges=dirty,dirty=s.isDirty,playing=Application.isPlaying,playerPosition=new[]{player.transform.position.x,player.transform.position.y,player.transform.position.z},playerRotation=new[]{player.transform.eulerAngles.x,player.transform.eulerAngles.y,player.transform.eulerAngles.z},runInBackground=PlayerSettings.runInBackground};File.WriteAllText(output+"final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}}
